int main(void){wchar_t temp[MAX_PATH],dir[MAX_PATH];DWORD n=GetTempPathW(MAX_PATH,temp);CHECK(n>0&&n<MAX_PATH);if(!n||n>=MAX_PATH)return 1;CHECK(GetTempFileNameW(temp,L"ZHC",0,dir)!=0);DeleteFileW(dir);CHECK(CreateDirectoryW(dir,NULL)!=0);ZDPaths paths={0};CHECK(to_utf8(dir,paths.exported,sizeof(paths.exported)));
    ZDHistoryEntry items[2]={0};items[0].id=42;items[0].url="https://zakon.rada.gov.ua/laws/show/42";items[0].status="Успішно";items[0].started_at="2026-10-30T10:00:00";items[0].document_title="Закон, \"Тест\"";items[0].saved_path="C:\\Документи\\law.txt";items[1].id=43;items[1].url="https://example.test/";items[1].status="Помилка";items[1].error_message="=HYPERLINK(\"bad\")";ZDHistoryList list={items,2};char output[ZD_PATH_MAX],error[512];CHECK(zd_history_export_csv(&paths,&list,output,sizeof(output),error,sizeof(error))==1);wchar_t wide[ZD_PATH_MAX];CHECK(MultiByteToWideChar(CP_UTF8,0,output,-1,wide,ZD_PATH_MAX)>0);HANDLE f=CreateFileW(wide,GENERIC_READ,FILE_SHARE_READ,NULL,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);CHECK(f!=INVALID_HANDLE_VALUE);if(f!=INVALID_HANDLE_VALUE){LARGE_INTEGER size;CHECK(GetFileSizeEx(f,&size)&&size.QuadPart<100000);char*data=(char*)malloc((size_t)size.QuadPart+1);DWORD got=0;CHECK(data&&ReadFile(f,data,(DWORD)size.QuadPart,&got,NULL)&&got==(DWORD)size.QuadPart);if(data){data[got]=0;CHECK(got>=3&&(unsigned char)data[0]==0xef&&(unsigned char)data[1]==0xbb&&(unsigned char)data[2]==0xbf);CHECK(strstr(data,"\"Закон, \"\"Тест\"\"\"")!=NULL);CHECK(strstr(data,"\"'=HYPERLINK(\"\"bad\"\")\"")!=NULL);free(data);}CloseHandle(f);DeleteFileW(wide);}RemoveDirectoryW(dir);if(failures){fprintf(stderr,"%d CSV export test(s) failed.\n",failures);return 1;}puts("History CSV export tests passed.");return 0;}
